Fixpoint art_rseg_ok (segs : list Segment) (a : word) (n : nat) : bool :=
  match n with
  | O => true
  | S n' => match seg_rom segs a with Some _ => art_rseg_ok segs (a + 1)%bv n' | None => false end
  end.

